const data = $json ?? {};

const execution = data.execution ?? {};
const workflow = data.workflow ?? {};
const trigger = data.trigger ?? {};

const error =
  execution.error ??
  trigger.error ??
  {};

const cause =
  error.cause ??
  {};

const failedNode =
  execution.lastNodeExecuted ??
  error.node?.name ??
  error.node?.type ??
  'Unknown node';

const errorMessage =
  error.message ??
  cause.message ??
  'Unknown workflow error';

const errorStack =
  error.stack ??
  cause.stack ??
  '';

return {
  json: {
    workflowName:
      workflow.name || 'Unknown workflow',

    workflowId:
      workflow.id || 'Unknown',

    executionId:
      execution.id || 'Unavailable',

    executionUrl:
      execution.url || '',

    failedNode,

    executionMode:
      execution.mode ||
      trigger.mode ||
      'unknown',

    errorName:
      error.name || 'WorkflowError',

    errorMessage,

    errorStack,

    retryOf:
      execution.retryOf || '',

    occurredAt:
      new Date().toISOString(),

    environment:
      'local-development'
  }
};
